// Package bfdemo is the playground for the guest-VM work: a realm that runs
// Brainfuck programs on chain, a slice at a time.
//
// It is a demo of two libraries and carries no logic of its own:
// [p/moul/x/vm/bf](/p/moul/x/vm/bf/v0) is the machine, and
// [p/moul/x/vm/vmkit](/p/moul/x/vm/vmkit/v0) is the host ABI, the fuel meter
// and the instance store.
//
// What it exists to show is the thing gno realm code cannot do for itself: a
// program that runs out of fuel does not fail, it pauses. The realm keeps the
// snapshot, and the next caller pays for the next slice. Upload a program,
// call Step a few times, and watch one computation finish across several
// transactions.
package bfdemo

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"time"

	"gno.land/p/moul/x/vm/bf/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Caps. Everything a caller can grow is bounded, because all of it is storage
// somebody pays a deposit on.
const (
	// MaxInstances is how many programs the realm keeps at once. Past it,
	// an upload has to wait for someone to remove one.
	MaxInstances = 64
	// MaxOutput caps the bytes one program may write. Past it the guest is
	// trapped rather than truncated, so rendered output is never a lie.
	MaxOutput = 4096
	// MaxInput caps the call input a program can be given.
	MaxInput = 1024
	// DefaultFuel is the budget an upload gets when it asks for none, and
	// the slice size Step uses when asked for none.
	DefaultFuel = 100000
	// MaxSliceFuel bounds one transaction's work regardless of what the
	// caller asked for.
	MaxSliceFuel = 5000000
)

var (
	// store holds the instances: program, snapshot, status, accounting.
	store = vmkit.NewStore()
	// inputs holds each instance's call input, keyed by id. It is separate
	// from the instance so vmkit.Instance stays the VM-agnostic record it
	// is meant to be.
	inputs = avl.NewTree()
	idgen  seqid.ID
	count  int
)

// host is the realm-backed [vmkit.Host]. One is built per call, wrapping the
// instance being stepped, so a guest's output and authority are scoped to it
// and nothing ambient leaks in.
type host struct {
	inst    *vmkit.Instance
	in      []byte
	kv      *avl.Tree
	overrun bool // the guest wrote past MaxOutput
}

func (h *host) Caller() address { return h.inst.Owner }
func (h *host) Origin() address { return h.inst.Owner }
func (h *host) Now() int64      { return time.Now().Unix() }
func (h *host) Height() int64   { return runtime.ChainHeight() }
func (h *host) Input() []byte   { return h.in }

// Get and Set are scoped to the instance by construction: the tree belongs to
// the instance being stepped, so one program cannot reach another's storage
// even though both live in this one realm. bf never calls them; they are here
// because the ABI is the point.
func (h *host) Get(key []byte) []byte {
	v := h.kv.Get(string(key))
	if v == nil {
		return nil
	}
	return v.([]byte)
}

func (h *host) Set(key, val []byte) { h.kv.Set(string(key), val) }

func (h *host) Output(p []byte) {
	if len(h.inst.Output)+len(p) > MaxOutput {
		h.overrun = true
		return
	}
	h.inst.Output = append(h.inst.Output, p...)
}

func (h *host) Emit(typ string, kv ...string) { chain.Emit(typ, kv...) }

// Send is never granted here. The demo funds no instance, so a guest that
// tries to move coins is refused. That is the capability rule doing its job,
// not a missing feature.
func (h *host) Send(to address, amount int64) error { return vmkit.ErrNotGranted }

func (h *host) Log(msg string) {}

// Upload compiles src and stores it as a new instance, returning its id.
//
// Compilation happens here rather than at the first Step, so an unbalanced
// program is rejected by the transaction that submitted it instead of costing
// somebody else the gas later.
func Upload(cur realm, src, input string, budget int64) string {
	if count >= MaxInstances {
		panic("bfdemo: too many instances, remove one first")
	}
	if len(input) > MaxInput {
		panic("bfdemo: input too long")
	}
	if _, err := bf.CompileDefault(src); err != nil {
		panic("bfdemo: " + err.Error())
	}
	if budget <= 0 {
		budget = DefaultFuel
	}

	id := idgen.Next().String()
	owner := unsafe.PreviousRealm().Address()
	store.Set(vmkit.NewInstance(id, owner, bf.VMName, []byte(src), budget))
	if input != "" {
		inputs.Set(id, input)
	}
	count++

	chain.Emit("bf_upload", "id", id, "bytes", ufmt.Sprintf("%d", len(src)))
	return id
}

// Step runs one slice of the instance: up to `fuel` guest ops, then stop and
// keep the snapshot. Anyone may pay for a slice, not only the owner: a paused
// program that only its owner can advance is a worse demo and no safer, since
// the program and its budget were both fixed at upload.
func Step(cur realm, id string, fuel int64) string {
	inst := store.Get(id)
	if inst == nil {
		panic("bfdemo: no such instance")
	}
	if inst.Status != vmkit.Running {
		panic("bfdemo: instance is " + inst.Status.String())
	}
	if fuel <= 0 {
		fuel = DefaultFuel
	}
	if fuel > MaxSliceFuel {
		fuel = MaxSliceFuel
	}

	prog, err := bf.CompileDefault(string(inst.Program))
	if err != nil {
		panic("bfdemo: " + err.Error())
	}
	h := &host{inst: inst, in: []byte(inputOf(id)), kv: avl.NewTree()}
	if err := inst.Run(bf.NewMachine(prog), h, fuel); err != nil {
		panic("bfdemo: " + err.Error())
	}
	if h.overrun {
		inst.Status = vmkit.Trapped
		inst.Trap = "output limit reached"
	}

	chain.Emit("bf_step",
		"id", id,
		"status", inst.Status.String(),
		"fuel", ufmt.Sprintf("%d", inst.FuelUsed),
	)
	return inst.Status.String()
}

// Remove deletes an instance. Owner only.
func Remove(cur realm, id string) {
	inst := store.Get(id)
	if inst == nil {
		panic("bfdemo: no such instance")
	}
	if inst.Owner != unsafe.PreviousRealm().Address() {
		panic("bfdemo: not your instance")
	}
	store.Remove(id)
	inputs.Remove(id)
	count--
}

func inputOf(id string) string {
	v := inputs.Get(id)
	if v == nil {
		return ""
	}
	return v.(string)
}

package bfdemo

import (
	"strings"
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const hello = "++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------."

// resetState puts the realm globals back where init() left them. Realm state
// persists for the whole test binary, so every test that asserts on ids or on
// the rendered instance list has to start from here.
func resetState() {
	store = vmkit.NewStore()
	inputs = avl.NewTree()
	idgen = seqid.ID(0)
	count = 0
}

func TestUploadAndRunToCompletion(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	id := Upload(cross(cur), hello, "", 0)
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))

	inst := store.Get(id)
	uassert.Equal(t, "Hello World", string(inst.Output))
	uassert.Equal(t, int64(1), inst.Slices)
	uassert.Equal(t, alice, inst.Owner)
}

// TestOneProgramAcrossManyTransactions is what the realm exists to
// demonstrate: the same computation, finished over several calls, each paying
// for its own slice.
func TestOneProgramAcrossManyTransactions(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	id := Upload(cross(cur), hello, "", 0)
	status := ""
	slices := 0
	for slices < 500 {
		status = Step(cross(cur), id, 7)
		slices++
		if status != "running" {
			break
		}
	}

	inst := store.Get(id)
	uassert.Equal(t, "halted", status)
	uassert.Equal(t, "Hello World", string(inst.Output))
	uassert.True(t, inst.Slices > 1, "took more than one slice")
}

func TestInputIsReadThroughTheHost(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// ",[.,]" echoes its input back.
	id := Upload(cross(cur), ",[.,]", "gno.land", 0)
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))
	uassert.Equal(t, "gno.land", string(store.Get(id).Output))
}

func TestBudgetStopsAProgram(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	id := Upload(cross(cur), hello, "", 12)
	uassert.Equal(t, "out of fuel", Step(cross(cur), id, 0))
	uassert.Equal(t, int64(12), store.Get(id).FuelUsed)

	// And it stays stopped rather than quietly continuing.
	uassert.AbortsContains(t, cur, "instance is out of fuel", func() {
		Step(cross(cur), id, 0)
	})
}

func TestUploadRejectsAMalformedProgram(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// Rejected by the transaction that submitted it, not by whoever pays
	// for the first slice later.
	uassert.AbortsContains(t, cur, "unmatched", func() {
		Upload(cross(cur), "+++[", "", 0)
	})
	uassert.Equal(t, 0, count)
}

func TestRemoveIsOwnerOnly(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Upload(cross(cur), hello, "", 0)

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "not your instance", func() {
		Remove(cross(cur), id)
	})

	// Anyone may pay for a slice, though: the program and its budget were
	// both fixed at upload.
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))

	testing.SetRealm(testing.NewUserRealm(alice))
	Remove(cross(cur), id)
	uassert.Equal(t, 0, count)
	uassert.True(t, store.Get(id) == nil)
}

func TestOutputIsCappedAndTrapped(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// A cell set to 1 and printed forever: an infinite writer.
	id := Upload(cross(cur), "+[.]", "", 0)
	status := Step(cross(cur), id, 0)

	inst := store.Get(id)
	uassert.Equal(t, "trapped", status)
	uassert.Equal(t, "output limit reached", inst.Trap)
	uassert.Equal(t, MaxOutput, len(inst.Output))
}

func TestRenderUnknownInstance(t *testing.T) {
	resetState()
	uassert.True(t, strings.Contains(Render("/nope"), "No such instance"))
}

// TestRenderEscapesGuestOutput pins the rule that a realm cannot be fixed in
// place once it is live: everything a caller controls is escaped before it
// reaches the page.
func TestRenderEscapesGuestOutput(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// Print a backtick (96), which would otherwise close the code fence.
	src := strings.Repeat("+", 96) + "."
	id := Upload(cross(cur), src, "", 0)
	Step(cross(cur), id, 0)

	page := Render("/" + id)
	uassert.Equal(t, "`", string(store.Get(id).Output))
	uassert.True(t, strings.Contains(page, "\\x60"), "the backtick is escaped")

	// The comment text in a program never reaches the page at all: only
	// the eight operators do.
	uassert.Equal(t, "+++[-]<>", operatorsOnly("+++ this is a comment [-] </script>"))
}

// Output sits in a code span, where markdown escapes show verbatim: only the
// pipe is escaped there, and nothing else.
func TestCodeCell(t *testing.T) {
	uassert.Equal(t, "`Hello, gno.land\\n`", codeCell("Hello, gno.land\\n"))
	uassert.Equal(t, "`a\\|b`", codeCell("a|b"))
}

// emit returns a program that prints s, one byte at a time, so a test can put
// any text in the output column without hand-writing Brainfuck.
func emit(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		sb.WriteString("[-]" + strings.Repeat("+", int(s[i])) + ".")
	}
	return sb.String()
}

// instanceRow returns the first instance row of the home page.
func instanceRow(t *testing.T) string {
	for _, line := range strings.Split(Render(""), "\n") {
		if strings.HasPrefix(line, "| [") {
			return line
		}
	}
	t.Fatalf("no instance row on the home page")
	return ""
}

// The output column is pinned on the rendered page, not only through the
// helper, so the call site cannot drift back to ui.Cell inside backticks
// (which would show `a\.b`) with the suite green.
func TestRenderOutputCell(cur realm, t *testing.T) {
	cases := []struct {
		name, out, cell string
	}{
		{"an escapable character shows as written", "a.b", "| `a.b` |"},
		{"no output is an empty cell, not two backticks", "", "| 0 |  |"},
		{"a space at each end is padded in the markdown, past CommonMark's strip", " a ", "| `  a  ` |"},
		{"a guest pipe stays inside its cell", "a|b", "| `a\\|b` |"},
	}
	for _, c := range cases {
		resetState()
		testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))
		id := Upload(cross(cur), emit(c.out), "", 0)
		if c.out != "" {
			Step(cross(cur), id, 0)
			uassert.Equal(t, c.out, string(store.Get(id).Output))
		}
		row := instanceRow(t)
		uassert.True(t, strings.HasSuffix(row, c.cell), c.name+": "+row)
	}
}

// codeCell follows the three rules of a code span, not only the pipe: empty
// content is not a span, a space at either end needs a pad, and the fence
// outscans any backtick run in the content.
func TestCodeCellRules(t *testing.T) {
	cases := []struct{ in, want string }{
		{"", ""},
		{"Hello World", "`Hello World`"},
		{"a|b", "`a\\|b`"},
		{" hi ", "`  hi  `"},
		{" hi", "`  hi `"},
		{"hi ", "` hi  `"},
		{"a`b", "``a`b``"},
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, codeCell(c.in), "codeCell("+c.in+")")
	}
}

package bfdemo

import (
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/x/vm/bf/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/ufmt/v0"
)

// samples are the programs the home page offers, so the realm is usable
// without writing Brainfuck by hand.
var samples = []struct {
	name  string
	src   string
	input string
	note  string
}{
	{
		"Hello World",
		"++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------.",
		"",
		"385 guest ops, five tape cells. Finishes in one slice.",
	},
	{
		"Echo the input",
		",[.,]",
		"gno.land",
		"Reads through Host.Input, which is what the naive interpreter could not do at all: it panicked on `,`.",
	},
	{
		"Heavy loop",
		"++++++++++[->++++++++++[->++++++++++[-]<]<]",
		"",
		"About 111k guest ops. Give it 20000 fuel and it takes six slices, which is the point.",
	},
}

// Render is the realm's gnoweb view.
//
//   - "/"      the samples, the instance list, and how the thing works.
//   - "/<id>"  one instance: its program, status, fuel and output.
func Render(path string) string {
	id := strings.TrimPrefix(path, "/")
	id = strings.TrimSpace(id)
	if id == "" {
		return renderHome()
	}
	return renderInstance(id)
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Brainfuck, on chain, a slice at a time\n\n")
	sb.WriteString("Demo of [`p/moul/x/vm/bf`](/p/moul/x/vm/bf/v0) (the machine) and ")
	sb.WriteString("[`p/moul/x/vm/vmkit`](/p/moul/x/vm/vmkit/v0) (the host ABI, the fuel meter, ")
	sb.WriteString("the instance store). This realm holds no logic of its own.\n\n")
	sb.WriteString("A program here does not run to completion. It runs until its fuel slice is spent, ")
	sb.WriteString("then pauses: the realm keeps the snapshot and the next caller pays for the next slice. ")
	sb.WriteString("Realm code cannot pause itself, and a guest can.\n\n")

	sb.WriteString("## Samples\n\n")
	for _, s := range samples {
		sb.WriteString("**" + ui.Inline(s.name) + "**: " + s.note + "\n\n")
		sb.WriteString("```\n" + s.src + "\n```\n\n")
		sb.WriteString(ui.Action("Upload "+s.name, "Upload",
			"src", s.src, "input", s.input, "budget", "0") + "\n\n")
	}

	sb.WriteString("## Instances\n\n")
	t := ui.NewTable("id", "status", "fuel used", "slices", "output")
	store.ReverseIterate(func(i *vmkit.Instance) bool {
		t.Row(
			"["+i.ID+"](/r/moul/x/vm/bfdemo/v0:"+i.ID+")",
			i.Status.String(),
			ufmt.Sprintf("%d", i.FuelUsed),
			ufmt.Sprintf("%d", i.Slices),
			codeCell(printable(i.Output, 24)),
		)
		return false
	})
	sb.WriteString(t.OrEmpty("No instances yet. Upload one of the samples above."))
	sb.WriteString("\n\n")

	sb.WriteString("## Limits\n\n")
	lt := ui.NewTable("limit", "value")
	lt.Row("instances", ufmt.Sprintf("%d", MaxInstances))
	lt.Row("source bytes", ufmt.Sprintf("%d", bf.MaxSource))
	lt.Row("input bytes", ufmt.Sprintf("%d", MaxInput))
	lt.Row("output bytes", ufmt.Sprintf("%d", MaxOutput))
	lt.Row("fuel per slice", ufmt.Sprintf("%d", MaxSliceFuel))
	lt.Row("tape cells", ufmt.Sprintf("%d", bf.TapeSize))
	sb.WriteString(lt.String())
	return sb.String()
}

func renderInstance(id string) string {
	var sb strings.Builder
	sb.WriteString("# Instance " + ui.Inline(id) + "\n\n")
	sb.WriteString("[← all instances](/r/moul/x/vm/bfdemo/v0)\n\n")

	inst := store.Get(id)
	if inst == nil {
		sb.WriteString("**No such instance.** It was never uploaded, or its owner removed it.\n")
		return sb.String()
	}

	t := ui.NewTable("field", "value")
	t.Row("owner", ui.Addr(inst.Owner))
	t.Row("vm", ui.Cell(inst.VM))
	t.Row("status", inst.Status.String())
	if inst.Trap != "" {
		t.Row("trap", ui.Cell(inst.Trap))
	}
	t.Row("fuel used", ufmt.Sprintf("%d", inst.FuelUsed))
	t.Row("fuel budget", fuelText(inst.FuelBudget))
	t.Row("slices", ufmt.Sprintf("%d", inst.Slices))
	t.Row("source bytes", ufmt.Sprintf("%d", len(inst.Program)))
	t.Row("snapshot bytes", ufmt.Sprintf("%d", len(inst.Snapshot)))
	sb.WriteString(t.String())
	sb.WriteString("\n")

	// The source is caller-supplied, and everything outside the eight
	// operators is a comment that may hold anything at all. Show the
	// program the machine actually compiled, which cannot contain a
	// backtick or a newline and so cannot break out of the fence.
	sb.WriteString("## Program\n\n```\n" + operatorsOnly(string(inst.Program)) + "\n```\n\n")

	sb.WriteString("## Output\n\n")
	if len(inst.Output) == 0 {
		sb.WriteString(ui.Empty("Nothing written yet."))
	} else {
		sb.WriteString("```\n" + printable(inst.Output, MaxOutput) + "\n```\n")
	}
	sb.WriteString("\n")

	if inst.Status == vmkit.Running {
		sb.WriteString(ui.Action("Run 10000 more fuel", "Step", "id", id, "fuel", "10000"))
		sb.WriteString(" · ")
		sb.WriteString(ui.Action("Run 100000 more fuel", "Step", "id", id, "fuel", "100000"))
		sb.WriteString("\n")
	} else {
		sb.WriteString("This instance is **" + inst.Status.String() + "** and cannot be stepped again.\n")
	}
	return sb.String()
}

func fuelText(n int64) string {
	if n == vmkit.Unmetered {
		return "unmetered"
	}
	return ufmt.Sprintf("%d", n)
}

// operatorsOnly strips a program down to the eight characters the language
// defines. Everything else is a comment by definition, and a comment is
// attacker-controlled text that has no business reaching a renderer.
func operatorsOnly(src string) string {
	var sb strings.Builder
	for i := 0; i < len(src); i++ {
		switch src[i] {
		case '+', '-', '<', '>', '[', ']', '.', ',':
			sb.WriteByte(src[i])
		}
	}
	if sb.Len() == 0 {
		return "(no operators: this program does nothing)"
	}
	return sb.String()
}

// printable renders guest output for a code fence: printable ASCII as itself,
// everything else as an escape. A guest writes arbitrary bytes, so this is
// the only form of it that is safe to show.
func printable(b []byte, max int) string {
	if len(b) == 0 {
		return ""
	}
	truncated := false
	if len(b) > max {
		b, truncated = b[:max], true
	}
	const hexDigits = "0123456789abcdef"
	var sb strings.Builder
	for _, c := range b {
		switch {
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\\':
			sb.WriteString("\\\\")
		case c == '`':
			sb.WriteString("\\x60")
		case c >= 0x20 && c < 0x7f:
			sb.WriteByte(c)
		default:
			sb.WriteString("\\x")
			sb.WriteByte(hexDigits[c>>4])
			sb.WriteByte(hexDigits[c&0x0f])
		}
	}
	if truncated {
		sb.WriteString("…")
	}
	return sb.String()
}

// codeCell puts already-printable text in a code span inside a table cell.
// Inside backticks markdown escapes are not applied, so ui.Cell's backslashes
// would reach the reader verbatim ("Hello, gno\.land"). md.InlineCode builds
// the span: empty text is no span at all (two bare backticks render as two
// backticks), a space at either end is padded so CommonMark's strip does not
// eat it, and the fence outscans any backtick run. The GFM row splitter runs
// before inline parsing, so the pipe is escaped on top.
func codeCell(s string) string {
	return strings.ReplaceAll(md.InlineCode(s), "|", "\\|")
}

package riscvdemo

import (
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/x/vm/riscv/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/moul/vendor/nt/ufmt/v2"
)

// regNames are the ABI names, because nobody reading a register dump thinks in
// x-numbers and every compiler's output is annotated with these.
var regNames = [32]string{
	"zero", "ra", "sp", "gp", "tp", "t0", "t1", "t2",
	"s0", "s1", "a0", "a1", "a2", "a3", "a4", "a5",
	"a6", "a7", "s2", "s3", "s4", "s5", "s6", "s7",
	"s8", "s9", "s10", "s11", "t3", "t4", "t5", "t6",
}

// Render is the realm's gnoweb view.
//
//   - "/"      the samples, the instance list, and what the numbers mean.
//   - "/<id>"  one instance: its status, fuel, output and register file.
func Render(path string) string {
	id := strings.TrimSpace(strings.TrimPrefix(path, "/"))
	if id == "" {
		return renderHome()
	}
	return renderInstance(id)
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# RV32IM, on chain, a slice at a time\n\n")
	sb.WriteString("Demo of [`p/moul/x/vm/riscv`](/p/moul/x/vm/riscv/v0) (the hart) and ")
	sb.WriteString("[`p/moul/x/vm/vmkit`](/p/moul/x/vm/vmkit/v0) (the host ABI, the fuel meter, ")
	sb.WriteString("the instance store). This realm holds no logic of its own.\n\n")
	sb.WriteString("The programs below are flat `.text` images: the same bytes a cross compiler ")
	sb.WriteString("emits for `riscv32im-unknown-none-elf`. Nothing here was written in a ")
	sb.WriteString("chain language, and nothing translated it.\n\n")
	sb.WriteString("A program does not run to completion. It runs until its fuel slice is spent, ")
	sb.WriteString("then pauses: the realm keeps the snapshot and the next caller pays for the ")
	sb.WriteString("next slice. Realm code cannot pause itself, and a guest can.\n\n")

	sb.WriteString("## Samples\n\n")
	for i := range samples {
		s := &samples[i]
		sb.WriteString("**" + ui.Inline(s.name) + "**: " + s.note + "\n\n")
		sb.WriteString("```" + s.lang() + "\n" + s.asm + "\n```\n\n")
		sb.WriteString(ui.Action("Upload "+s.name, "UploadSample",
			"name", s.slug, "input", s.input,
			"budget", ufmt.Sprintf("%d", s.budget)) + "\n\n")
	}

	sb.WriteString("## Instances\n\n")
	t := ui.NewTable("id", "status", "instructions", "slices", "output")
	store.ReverseIterate(func(i *vmkit.Instance) bool {
		t.Row(
			"["+i.ID+"](/r/moul/x/vm/riscvdemo/v0:"+i.ID+")",
			i.Status.String(),
			ufmt.Sprintf("%d", i.FuelUsed),
			ufmt.Sprintf("%d", i.Slices),
			codeCell(printable(i.Output, 24)),
		)
		return false
	})
	sb.WriteString(t.OrEmpty("No instances yet. Upload one of the samples above."))
	sb.WriteString("\n\n")

	sb.WriteString("## What a slice costs\n\n")
	sb.WriteString("An RV32IM instruction costs about **8,500 gas** here, measured rather than ")
	sb.WriteString("estimated, so a block buys roughly **350,000 guest instructions**. Loading ")
	sb.WriteString("the image costs about **19,600 gas per instruction word** and is paid again ")
	sb.WriteString("on every resume, which is why the image cap below is small. The numbers and ")
	sb.WriteString("how they were taken are in the [library README](/p/moul/x/vm/riscv/v0).\n\n")

	sb.WriteString("## Limits\n\n")
	lt := ui.NewTable("limit", "value")
	lt.Row("instances", ufmt.Sprintf("%d", MaxInstances))
	lt.Row("image bytes", ufmt.Sprintf("%d", MaxImage))
	lt.Row("input bytes", ufmt.Sprintf("%d", MaxInput))
	lt.Row("output bytes", ufmt.Sprintf("%d", MaxOutput))
	lt.Row("instructions per slice", ufmt.Sprintf("%d", MaxSliceFuel))
	lt.Row("address space", ufmt.Sprintf("%d", riscv.MemSize))
	sb.WriteString(lt.String())
	return sb.String()
}

func renderInstance(id string) string {
	var sb strings.Builder
	sb.WriteString("# Instance " + ui.Inline(id) + "\n\n")
	sb.WriteString("[← all instances](/r/moul/x/vm/riscvdemo/v0)\n\n")

	inst := store.Get(id)
	if inst == nil {
		sb.WriteString("**No such instance.** It was never uploaded, or its owner removed it.\n")
		return sb.String()
	}

	t := ui.NewTable("field", "value")
	t.Row("owner", ui.Addr(inst.Owner))
	t.Row("vm", ui.Cell(inst.VM))
	t.Row("status", inst.Status.String())
	if inst.Trap != "" {
		t.Row("trap", ui.Cell(inst.Trap))
	}
	t.Row("instructions run", ufmt.Sprintf("%d", inst.FuelUsed))
	t.Row("budget", fuelText(inst.FuelBudget))
	t.Row("slices", ufmt.Sprintf("%d", inst.Slices))
	t.Row("image bytes", ufmt.Sprintf("%d", len(inst.Program)))
	t.Row("image words", ufmt.Sprintf("%d", len(inst.Program)/4))
	t.Row("snapshot bytes", ufmt.Sprintf("%d", len(inst.Snapshot)))
	sb.WriteString(t.String())
	sb.WriteString("\n")

	sb.WriteString("## Registers\n\n")
	sb.WriteString(renderRegisters(inst))

	sb.WriteString("## Output\n\n")
	if len(inst.Output) == 0 {
		sb.WriteString(ui.Empty("Nothing written yet."))
	} else {
		sb.WriteString("```\n" + printable(inst.Output, MaxOutput) + "\n```\n")
	}
	sb.WriteString("\n")

	sb.WriteString("## Image\n\n```\n" + hexDump(inst.Program, 64) + "\n```\n\n")

	if inst.Status == vmkit.Running {
		sb.WriteString(ui.Action("Run 25000 instructions", "Step", "id", id, "fuel", "25000"))
		sb.WriteString(" · ")
		sb.WriteString(ui.Action("Run 100000 instructions", "Step", "id", id, "fuel", "100000"))
		sb.WriteString("\n")
	} else {
		sb.WriteString("This instance is **" + inst.Status.String() + "** and cannot be stepped again.\n")
	}
	return sb.String()
}

// renderRegisters restores the snapshot to read the register file out of it.
// The hart is not kept between transactions, only its snapshot is, so this is
// the only place the state is legible, and it is the thing worth seeing: a
// program that wrote nothing still computed something.
func renderRegisters(inst *vmkit.Instance) string {
	if len(inst.Snapshot) == 0 {
		return ui.Empty("Not started yet: no snapshot to read.") + "\n\n"
	}
	var m riscv.Machine
	if err := m.Restore(inst.Snapshot); err != nil {
		return ui.Empty("The snapshot could not be read.") + "\n\n"
	}
	reg := m.Registers()

	var sb strings.Builder
	t := ui.NewTable("register", "hex", "unsigned", "signed")
	t.Row("pc", ufmt.Sprintf("0x%08X", m.PC()), "", "")
	shown := 0
	for i := 1; i < 32; i++ {
		if reg[i] == 0 {
			continue
		}
		t.Row(
			regNames[i],
			ufmt.Sprintf("0x%08X", reg[i]),
			ufmt.Sprintf("%d", reg[i]),
			ufmt.Sprintf("%d", int64(int32(reg[i]))),
		)
		shown++
	}
	sb.WriteString(t.String())
	if shown == 0 {
		sb.WriteString("\nEvery register except `pc` is zero.\n")
	}
	sb.WriteString("\n")
	return sb.String()
}

func fuelText(n int64) string {
	if n == vmkit.Unmetered {
		return "unmetered"
	}
	return ufmt.Sprintf("%d", n)
}

const hexDigits = "0123456789abcdef"

// hexDump shows the image as words, which is how anyone reading RV32 reads it.
func hexDump(b []byte, max int) string {
	truncated := false
	if len(b) > max {
		b, truncated = b[:max], true
	}
	var sb strings.Builder
	for i := 0; i+3 < len(b); i += 4 {
		if i > 0 && i%16 == 0 {
			sb.WriteString("\n")
		} else if i > 0 {
			sb.WriteString(" ")
		}
		w := uint32(b[i]) | uint32(b[i+1])<<8 | uint32(b[i+2])<<16 | uint32(b[i+3])<<24
		sb.WriteString(ufmt.Sprintf("%08x", w))
	}
	if truncated {
		sb.WriteString("\n...")
	}
	return sb.String()
}

// printable renders guest output for a code fence: printable ASCII as itself,
// everything else as an escape. A guest writes arbitrary bytes, so this is the
// only form of it that is safe to show.
func printable(b []byte, max int) string {
	if len(b) == 0 {
		return ""
	}
	truncated := false
	if len(b) > max {
		b, truncated = b[:max], true
	}
	var sb strings.Builder
	for _, c := range b {
		switch {
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\\':
			sb.WriteString("\\\\")
		case c == '`':
			sb.WriteString("\\x60")
		case c >= 0x20 && c < 0x7f:
			sb.WriteByte(c)
		default:
			sb.WriteString("\\x")
			sb.WriteByte(hexDigits[c>>4])
			sb.WriteByte(hexDigits[c&0x0f])
		}
	}
	if truncated {
		sb.WriteString("…")
	}
	return sb.String()
}

// codeCell puts already-printable text in a code span inside a table cell.
// Inside backticks markdown escapes are not applied, so ui.Cell's backslashes
// would reach the reader verbatim ("Hello, gno\.land"). md.InlineCode builds
// the span: empty text is no span at all (two bare backticks render as two
// backticks), a space at either end is padded so CommonMark's strip does not
// eat it, and the fence outscans any backtick run. The GFM row splitter runs
// before inline parsing, so the pipe is escaped on top.
func codeCell(s string) string {
	return strings.ReplaceAll(md.InlineCode(s), "|", "\\|")
}

// Package riscvdemo runs real compiled machine code on chain, a slice at a
// time.
//
// It is a demo of two libraries and carries no logic of its own:
// [p/moul/x/vm/riscv](/p/moul/x/vm/riscv/v0) is the RV32IM hart, and
// [p/moul/x/vm/vmkit](/p/moul/x/vm/vmkit/v0) is the host ABI, the fuel meter
// and the instance store.
//
// What it exists to show is that the guest was not written for gno. The
// programs on the front page are flat .text images: the same bytes
// `rustc --target riscv32im-unknown-none-elf` emits, uploaded as hex. The
// realm holds the snapshot between transactions, so one computation finishes
// across several of them, and realm code cannot do that for itself.
package riscvdemo

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"time"

	"gno.land/p/moul/x/vm/riscv/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/moul/vendor/nt/ufmt/v2"
)

// Caps. Everything a caller can grow is bounded, because all of it is storage
// somebody pays a deposit on.
const (
	// MaxInstances is how many programs the realm keeps at once.
	MaxInstances = 64
	// MaxImage caps an uploaded text segment at 2,048 instructions.
	//
	// This one is not arbitrary. Predecoding costs about 19,600 gas per word
	// and is redone on every resume, so the image size is a tax on every
	// transaction that touches the instance, not just the upload. 8 KiB works
	// out to roughly 40M gas per slice before the guest executes anything,
	// which is about 1% of a block.
	MaxImage = 8192
	// MaxOutput caps the bytes one program may write. Past it the guest is
	// trapped rather than truncated, so rendered output is never a lie.
	MaxOutput = 4096
	// MaxInput caps the call input a program can be given.
	MaxInput = 1024
	// DefaultFuel is the budget an upload gets when it asks for none, and the
	// slice size Step uses when asked for none.
	DefaultFuel = 100000
	// MaxSliceFuel bounds one transaction's work regardless of what the
	// caller asked for, and it is derived from the measurement rather than
	// picked: an RV32IM instruction costs about 8,500 gas, so 100,000 of them
	// is about 850M, a little under a third of a 3G block. Twice this would
	// still be a legal transaction and a rude one, and it would leave no room
	// for the predecode and the realm's own storage writes on top.
	MaxSliceFuel = 100000
)

var (
	store  = vmkit.NewStore()
	inputs = avl.NewTree()
	idgen  seqid.ID
	count  int
)

// host is the realm-backed [vmkit.Host]. One is built per call, wrapping the
// instance being stepped, so a guest's output and authority are scoped to it
// and nothing ambient leaks in.
type host struct {
	inst    *vmkit.Instance
	in      []byte
	kv      *avl.Tree
	overrun bool // the guest wrote past MaxOutput
}

func (h *host) Caller() address { return h.inst.Owner }
func (h *host) Origin() address { return h.inst.Owner }
func (h *host) Now() int64      { return time.Now().Unix() }
func (h *host) Height() int64   { return runtime.ChainHeight() }
func (h *host) Input() []byte   { return h.in }

// Get and Set are scoped to the instance by construction: the tree belongs to
// the instance being stepped, so one program cannot reach another's storage
// even though both live in this one realm.
func (h *host) Get(key []byte) []byte {
	v := h.kv.Get(string(key))
	if v == nil {
		return nil
	}
	return v.([]byte)
}

func (h *host) Set(key, val []byte) { h.kv.Set(string(key), val) }

func (h *host) Output(p []byte) {
	if len(h.inst.Output)+len(p) > MaxOutput {
		h.overrun = true
		return
	}
	h.inst.Output = append(h.inst.Output, p...)
}

func (h *host) Emit(typ string, kv ...string) { chain.Emit(typ, kv...) }

// Send is never granted here. The demo funds no instance, so a guest that
// tries to move coins is refused. That is the capability rule doing its job,
// not a missing feature.
func (h *host) Send(to address, amount int64) error { return vmkit.ErrNotGranted }

func (h *host) Log(msg string) {}

// Upload stores a hex-encoded text image as a new instance and returns its id.
//
// The image is loaded here rather than at the first Step, so a misaligned or
// oversized one is rejected by the transaction that submitted it instead of
// costing somebody else the gas later.
func Upload(cur realm, hexImage, input string, budget int64) string {
	img, ok := decodeHex(hexImage)
	if !ok {
		panic("riscvdemo: image is not valid hex")
	}
	return upload(img, input, budget)
}

// UploadSample stores one of the programs the front page offers. Writing RV32IM
// by hand is not the point of this realm, and without this nobody without a
// cross compiler could press a button.
func UploadSample(cur realm, name, input string, budget int64) string {
	s := sampleByName(name)
	if s == nil {
		panic("riscvdemo: no such sample")
	}
	// A sample carries its own budget because the default is a total, not a
	// slice: the heavy loop needs 200,006 instructions, and offering a button
	// that runs out of fuel halfway is a worse demo than no button.
	if budget <= 0 {
		budget = s.budget
	}
	return upload(s.image(), input, budget)
}

func upload(img []byte, input string, budget int64) string {
	if count >= MaxInstances {
		panic("riscvdemo: too many instances, remove one first")
	}
	if len(input) > MaxInput {
		panic("riscvdemo: input too long")
	}
	if len(img) == 0 {
		panic("riscvdemo: empty image")
	}
	if len(img) > MaxImage {
		panic("riscvdemo: image too large")
	}
	// Loading it now is the validation: NewMachine is what rejects an image
	// that is not a whole number of instructions.
	if _, err := riscv.NewMachine(img, riscv.DefaultEntry); err != nil {
		panic("riscvdemo: " + err.Error())
	}
	if budget <= 0 {
		budget = DefaultFuel
	}

	id := idgen.Next().String()
	owner := unsafe.PreviousRealm().Address()
	store.Set(vmkit.NewInstance(id, owner, riscv.VMName, img, budget))
	if input != "" {
		inputs.Set(id, input)
	}
	count++

	chain.Emit("riscv_upload", "id", id, "bytes", ufmt.Sprintf("%d", len(img)))
	return id
}

// Step runs one slice of the instance: up to `fuel` guest instructions, then
// stop and keep the snapshot. Anyone may pay for a slice, not only the owner:
// a paused program that only its owner can advance is a worse demo and no
// safer, since the program and its budget were both fixed at upload.
func Step(cur realm, id string, fuel int64) string {
	inst := store.Get(id)
	if inst == nil {
		panic("riscvdemo: no such instance")
	}
	if inst.Status != vmkit.Running {
		panic("riscvdemo: instance is " + inst.Status.String())
	}
	if fuel <= 0 {
		fuel = DefaultFuel
	}
	if fuel > MaxSliceFuel {
		fuel = MaxSliceFuel
	}

	m, err := riscv.NewMachine(inst.Program, riscv.DefaultEntry)
	if err != nil {
		panic("riscvdemo: " + err.Error())
	}
	h := &host{inst: inst, in: []byte(inputOf(id)), kv: avl.NewTree()}
	if err := inst.Run(m, h, fuel); err != nil {
		panic("riscvdemo: " + err.Error())
	}
	if h.overrun {
		inst.Status = vmkit.Trapped
		inst.Trap = "output limit reached"
	}

	chain.Emit("riscv_step",
		"id", id,
		"status", inst.Status.String(),
		"fuel", ufmt.Sprintf("%d", inst.FuelUsed),
	)
	return inst.Status.String()
}

// Remove deletes an instance. Owner only.
func Remove(cur realm, id string) {
	inst := store.Get(id)
	if inst == nil {
		panic("riscvdemo: no such instance")
	}
	if inst.Owner != unsafe.PreviousRealm().Address() {
		panic("riscvdemo: not your instance")
	}
	store.Remove(id)
	inputs.Remove(id)
	count--
}

func inputOf(id string) string {
	v := inputs.Get(id)
	if v == nil {
		return ""
	}
	return v.(string)
}

// decodeHex accepts the output of any hexdump: an even number of hex digits,
// with an optional 0x prefix, and whitespace anywhere. Whitespace is allowed
// because that is what a pasted hexdump has in it; anything else is refused,
// because a silently mangled image would trap somewhere unrelated later.
func decodeHex(s string) ([]byte, bool) {
	if len(s) >= 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X') {
		s = s[2:]
	}
	digits := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			continue
		}
		v, ok := hexVal(c)
		if !ok {
			return nil, false
		}
		digits = append(digits, v)
	}
	if len(digits) == 0 || len(digits)%2 != 0 {
		return nil, false
	}
	out := make([]byte, len(digits)/2)
	for i := 0; i < len(out); i++ {
		out[i] = digits[i*2]<<4 | digits[i*2+1]
	}
	return out, true
}

func hexVal(c byte) (byte, bool) {
	switch {
	case c >= '0' && c <= '9':
		return c - '0', true
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10, true
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}

package riscvdemo

import (
	"strings"
	"testing"

	"gno.land/p/moul/x/vm/riscv/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// resetState puts the realm globals back where init() left them. Realm state
// persists for the whole test binary, so every test that asserts on ids or on
// the rendered instance list has to start from here.
func resetState() {
	store = vmkit.NewStore()
	inputs = avl.NewTree()
	idgen = seqid.ID(0)
	count = 0
}

func alice() address { return testutils.TestAddress("alice") }

func TestUploadAndRunToCompletion(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	id := UploadSample(cross(cur), "hello", "", 0)
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))

	inst := store.Get(id)
	uassert.Equal(t, "Hello, gno.land\n", string(inst.Output))
	uassert.Equal(t, int64(1), inst.Slices)
	uassert.Equal(t, alice(), inst.Owner)
	uassert.Equal(t, "riscv32im", inst.VM)
}

// Every sample on the front page has to reach its documented answer, or the
// page offers a button that traps when pressed. The words are assembled
// outside this repo, so this is the test that catches a mistyped one.
func TestEverySampleReachesItsAnswer(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	cases := []struct {
		slug   string
		reg    int
		want   uint32
		output string
	}{
		{"hello", 0, 0, "Hello, gno.land\n"},
		{"sum100", 5, 5050, ""},
		{"heavy", 5, 1250025000, ""},
		{"mext", 5, 3000000021, ""},
		{"clang", 0, 0, "fb7ffba0"},
		{"ledger", 0, 0, "alice 70\nbob 80\n"},
	}
	for _, c := range cases {
		id := UploadSample(cross(cur), c.slug, sampleByName(c.slug).input, 0)
		status := ""
		for i := 0; i < 20; i++ {
			status = Step(cross(cur), id, 0)
			if status != "running" {
				break
			}
		}
		uassert.Equal(t, "halted", status, c.slug+" must halt")
		inst := store.Get(id)
		uassert.Equal(t, c.output, string(inst.Output), c.slug+" output")
		if c.reg != 0 {
			var m riscv.Machine
			uassert.NoError(t, m.Restore(inst.Snapshot))
			uassert.Equal(t, uint64(c.want), uint64(m.Registers()[c.reg]), c.slug+" result")
		}
	}
}

// TestOneProgramAcrossManyTransactions is what the realm exists to
// demonstrate: the same computation, finished over several calls, each paying
// for its own slice.
func TestOneProgramAcrossManyTransactions(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	id := UploadSample(cross(cur), "heavy", "", 0)
	status := ""
	for i := 0; i < 50; i++ {
		status = Step(cross(cur), id, 80000)
		if status != "running" {
			break
		}
	}
	inst := store.Get(id)
	uassert.Equal(t, "halted", status)
	uassert.True(t, inst.Slices > 1, "a 200k instruction program must not finish in one slice")
	uassert.Equal(t, int64(200006), inst.FuelUsed)
}

func TestUploadTakesHex(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	// addi a7, zero, 93 ; ecall
	id := Upload(cross(cur), "0x9308d005 73000000", "", 0)
	_ = id
}

func TestUploadRejectsBadImages(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	// Called without cross(): a panic raised through a crossing call cannot be
	// recovered, so uassert would never see it.
	uassert.PanicsWithMessage(t, cur, "riscvdemo: image is not valid hex", func() {
		Upload(cur, "zzzz", "", 0)
	})
	uassert.PanicsWithMessage(t, cur, "riscvdemo: image is not valid hex", func() {
		Upload(cur, "abc", "", 0)
	})
	uassert.PanicsWithMessage(t, cur, "riscvdemo: no such sample", func() {
		UploadSample(cur, "nope", "", 0)
	})
	uassert.PanicsWithMessage(t, cur,
		"riscvdemo: riscv: image length is not a whole number of instructions",
		func() { Upload(cur, "0011", "", 0) })
}

func TestDecodeHex(t *testing.T) {
	b, ok := decodeHex("0xDEADbeef")
	uassert.True(t, ok)
	uassert.Equal(t, 4, len(b))
	uassert.Equal(t, uint64(0xDE), uint64(b[0]))
	uassert.Equal(t, uint64(0xEF), uint64(b[3]))

	_, ok = decodeHex("")
	uassert.False(t, ok)
	_, ok = decodeHex("0x")
	uassert.False(t, ok)
	// Whitespace is skipped, because a pasted hexdump has it.
	b, ok = decodeHex("00 11\n22\t33")
	uassert.True(t, ok)
	uassert.Equal(t, 4, len(b))
	// An odd number of digits is still a refusal, whitespace or not.
	_, ok = decodeHex("00 1")
	uassert.False(t, ok)
}

func TestRenderHomeOffersEverySample(cur realm, t *testing.T) {
	resetState()
	out := Render("")
	uassert.True(t, strings.Contains(out, "RV32IM, on chain"), "the title")
	for _, s := range samples {
		uassert.True(t, strings.Contains(out, s.name), "home must offer "+s.slug)
	}
	uassert.True(t, strings.Contains(out, "No instances yet"), "the empty state")
}

// The register file is the interesting half of this VM: a program that writes
// nothing still computed something, and the snapshot is the only place it is
// legible between transactions.
func TestRenderInstanceShowsTheRegisterFile(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	id := UploadSample(cross(cur), "sum100", "", 0)
	Step(cross(cur), id, 0)

	out := Render("/" + id)
	uassert.True(t, strings.Contains(out, "## Registers"), "the section")
	uassert.True(t, strings.Contains(out, "5050"), "t0 must show the answer")
	uassert.True(t, strings.Contains(out, "halted"), "the status")
}

// The instance page is all hex: the pc, every register, the image dump.
// gno.land/p/nt/ufmt/v0 has no %X and no width flags, so this page shipped
// printing "0x(unhandled verb: %X)" in every cell; the test pins the fix.
func TestRenderInstanceHex(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	// addi a7, zero, 93 ; ecall (exit)
	id := Upload(cross(cur), "0x9308d005 73000000", "", 0)
	Step(cross(cur), id, 0)

	out := Render("/" + id)
	uassert.False(t, strings.Contains(out, "unhandled"), out)
	uassert.True(t, strings.Contains(out, "| a7 | 0x0000005D | 93 | 93 |"), out)
	uassert.True(t, strings.Contains(out, "05d00893 00000073"), out)
}

// The instance list shows output in a code span, where markdown escapes do
// not apply: ui.Cell's backslashes used to reach the reader as
// `Hello, gno\.land\\n`. Only the pipe needs escaping inside the span.
func TestRenderOutputCell(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))

	id := UploadSample(cross(cur), "hello", "", 0)
	Step(cross(cur), id, 0)

	out := Render("")
	uassert.True(t, strings.Contains(out, "| `Hello, gno.land\\n` |"), out)
	uassert.Equal(t, "`a\\|b`", codeCell("a|b"))
}

func TestRenderUnknownInstance(t *testing.T) {
	uassert.True(t, strings.Contains(Render("/nope"), "No such instance"))
}

// ExampleRender pins the realm's output for a path whose content cannot drift
// with the instance list. The home page and the instance page both produce
// consecutive blank lines, which an example block cannot represent, so they
// are asserted in the tests above instead.
func ExampleRender() {
	print(Render("/missing"))
	// Output:
	// # Instance missing
	//
	// [← all instances](/r/moul/x/vm/riscvdemo/v0)
	//
	// **No such instance.** It was never uploaded, or its owner removed it.
}

// An instance that has written nothing yet shows an empty output cell. Two
// adjacent backticks are not an empty code span, they render as two
// backticks.
func TestRenderEmptyOutputCell(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice()))
	UploadSample(cross(cur), "hello", "", 0)

	row := ""
	for _, line := range strings.Split(Render(""), "\n") {
		if strings.HasPrefix(line, "| [") {
			row = line
		}
	}
	uassert.True(t, row != "", "an instance row is rendered")
	uassert.True(t, strings.HasSuffix(row, "| 0 |  |"), row)
}

// codeCell follows the three rules of a code span, not only the pipe: empty
// content is not a span, a space at either end needs a pad, and the fence
// outscans any backtick run in the content.
func TestCodeCellRules(t *testing.T) {
	cases := []struct{ in, want string }{
		{"", ""},
		{"Hello, gno.land\\n", "`Hello, gno.land\\n`"},
		{"a|b", "`a\\|b`"},
		{" hi ", "`  hi  `"},
		{" hi", "`  hi `"},
		{"hi ", "` hi  `"},
		{"a`b", "``a`b``"},
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, codeCell(c.in), "codeCell("+c.in+")")
	}
}

package riscvdemo

import "gno.land/p/moul/x/vm/riscv/v0"

// The programs the front page offers, as the machine words a cross compiler
// would have emitted. They are assembled outside this repo and pinned here,
// and riscvdemo_test.gno runs every one of them to the expected answer, so a
// wrong word is a failing test rather than a page that traps when clicked.
type sample struct {
	slug   string // what UploadSample takes: short, no punctuation, stable
	name   string
	budget int64 // the instance's total instruction budget, not the slice

	// builtin names an image the library ships compiled, instead of the words
	// below. Empty means the words are the program.
	builtin string
	words []uint32
	input string
	note  string
	asm   string
}

var samples = []sample{
	{
		slug: "hello",
		name: "Hello, gno.land",
		words: []uint32{
			0x00100513, 0x000015B7, 0x02058593, 0x01000613,
			0x04000893, 0x00000073, 0x05D00893, 0x00000073,
			0x6C6C6548, 0x67202C6F, 0x6C2E6F6E, 0x0A646E61,
		},
		budget: 1000,
		note: "Eight instructions and a string constant. The write syscall reads " +
			"the bytes straight out of the text segment and hands them to Host.Output.",
		asm: `addi a0, zero, 1          # fd
lui  a1, 0x1000           # buf
addi a1, a1, 0x20
addi a2, zero, 16         # len
addi a7, zero, 64         # write
ecall
addi a7, zero, 93         # exit
ecall
.ascii "Hello, gno.land\n"`,
	},
	{
		slug: "sum100",
		name: "Sum 1 to 100",
		words: []uint32{
			0x06400413, 0x00000293, 0x00000313, 0x00130313,
			0x006282B3, 0xFE831CE3, 0x05D00893, 0x00000073,
		},
		budget: 1000,
		note: "A real loop, 303 instructions. Writes nothing: the answer is in t0, " +
			"and the instance page shows the register file.",
		asm: `addi s0, zero, 100
addi t0, zero, 0
addi t1, zero, 0
loop:
addi t1, t1, 1
add  t0, t0, t1
bne  t1, s0, loop
addi a7, zero, 93
ecall`,
	},
	{
		slug: "heavy",
		name: "Heavy loop",
		words: []uint32{
			0x0000C437, 0x35040413, 0x00000293, 0x00000313,
			0x00130313, 0x006282B3, 0x00000393, 0xFE831AE3,
			0x05D00893, 0x00000073,
		},
		budget: 250000,
		note: "200,006 instructions, four per iteration. At the largest slice this realm " +
			"allows it takes three transactions to finish, which is the thing it exists to show.",
		asm: `lui  s0, 0xc000           # s0 = 50000
addi s0, s0, 0x350
addi t0, zero, 0
addi t1, zero, 0
loop:
addi t1, t1, 1
add  t0, t0, t1
addi t2, zero, 0
bne  t1, s0, loop
addi a7, zero, 93
ecall`,
	},
	{
		slug: "mext",
		name: "Multiply and divide",
		words: []uint32{
			0x3B9AD2B7, 0xA0728293, 0x00300313, 0x026282B3,
			0x00700393, 0x0272D333, 0x05D00893, 0x00000073,
		},
		budget: 1000,
		note: "The M extension. t0 = 1000000007 * 3 truncated to 32 bits, then t1 = t0 / 7. " +
			"Division by zero and the one signed overflow case return values here " +
			"rather than trapping, which is what the spec says and what a chain needs.",
		asm: `lui  t0, 0x3b9ad000       # t0 = 1000000007
addi t0, t0, -1529
addi t1, zero, 3
mul  t0, t0, t1
addi t2, zero, 7
divu t1, t0, t2
addi a7, zero, 93
ecall`,
	},
	{
		slug:   "clang",
		name:   "Compiled by clang",
		input:  "gno.land",
		budget: 20000,
		note: "Not written for gno and not written by hand: a freestanding C program, " +
			"compiled by clang for riscv32im and shipped as the bytes LLVM emitted. It reads " +
			"the call input, hashes it with FNV-1a and writes eight hex digits back. " +
			"With the default input it prints fb7ffba0. Source and build command: " +
			"tools/riscv-guests/fnv.",
		builtin: "fnv",
		asm: `long n = syscall3(SYS_READ, 0, (long)in, sizeof(in));

unsigned int h = 2166136261u;
for (long i = 0; i < n; i++) {
	h ^= in[i];
	h *= 16777619u;      /* the reason this is rv32im */
}

for (int i = 0; i < 8; i++) {
	unsigned int nib = (h >> (28 - i * 4)) & 0xF;
	out[i] = nib < 10 ? '0' + nib : 'a' + (nib - 10);
}

syscall3(SYS_WRITE, 1, (long)out, 8);
syscall3(SYS_EXIT, 0, 0, 0);`,
	},
	{
		slug:   "ledger",
		name:   "A token, in Rust",
		input:  "mint alice 100\nmint bob 50\nsend alice bob 30\n",
		budget: 20000,
		note: "no_std Rust, compiled by rustc for riscv32im: mint, send and burn, applied " +
			"from the call input. It links Rust's real core and compiler_builtins, so the " +
			"balances being 64-bit means a divide runs __udivdi3 here, because RV32 has no " +
			"64-bit divide instruction. With the default input it prints alice 70 and bob 80. " +
			"Source: tools/riscv-guests/ledger.",
		builtin: "ledger",
		asm: `match cmd {
	b"send" => {
		let (from, rest) = field(rest);
		let (to, rest) = field(rest);
		let (amount, _) = field(rest);
		let n = parse_u32(amount).ok_or("bad amount")?;
		let fi = led.find(from).ok_or("unknown sender")?;
		if led.balances[fi] < n {
			return Err("insufficient balance");
		}
		let ti = led.intern(to).ok_or("ledger full or bad name")?;
		led.balances[fi] -= n;
		led.balances[ti] += n;
		Ok(())
	}
	_ => Err("unknown command"),
}`,
	},
}

// image is what gets uploaded: either the words assembled here, or a program
// the library ships because a compiler produced it.
func (s *sample) image() []byte {
	switch s.builtin {
	case "fnv":
		return riscv.GuestFNV()
	case "ledger":
		return riscv.GuestLedger()
	}
	return riscv.Image(s.words)
}

// lang is the fence tag for what the sample shows. The compiled guest shows
// its C, because showing a disassembly of what LLVM did with it would bury the
// only interesting fact: nobody wrote the machine code.
func (s *sample) lang() string {
	switch s.builtin {
	case "fnv":
		return "c"
	case "ledger":
		return "rust"
	}
	return "asm"
}

func sampleByName(slug string) *sample {
	for i := range samples {
		if samples[i].slug == slug {
			return &samples[i]
		}
	}
	return nil
}

package crews

import (
	"strconv"
	"strings"
	"testing"
)

// Finding 325-cost-at-caps-1. A crew's page rendered every proposal the crew
// had ever had. Proposing is open to every member and nothing deletes one, so
// the cost every reader of that page paid grew without a bound anybody
// controls.
//
// Both comparison points are above the cap on purpose: comparing a count below
// it with one above measures the cap arriving, not the page being bounded.
func TestACrewPageIsBoundedByWhatItShows(cur realm, t *testing.T) {
	reset()
	id := create(cur, alice, 1000000, "the crew")

	for i := 0; i < 40; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	small := Render("crew/" + strconv.FormatInt(id, 10))

	for i := 40; i < 200; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	big := Render("crew/" + strconv.FormatInt(id, 10))

	rowsSmall := strings.Count(small, "\n|")
	rowsBig := strings.Count(big, "\n|")
	if rowsSmall == 0 {
		t.Fatal("no table rows rendered at all, so this test is measuring nothing")
	}
	if rowsBig > rowsSmall {
		t.Errorf("the crew page grew from %d rows to %d when the proposals went from 40 to 200: "+
			"every reader pays for every proposal the crew has ever had", rowsSmall, rowsBig)
	}
}

// Package crews is small-group coordination you can create in one
// transaction: three to fifteen people with a shared pot, a way to decide, and
// a way to leave with their share.
//
// It is the chain wiring for [gno.land/p/moul/x/social/crew], which holds the
// share math and the proposal state. This realm reads the caller, reads the
// coins attached to the call, asks the engine, and renders the result.
//
//	Create    pay in, and you are the crew's first member
//	Join      pay in at what a share is worth NOW, not at what it cost them
//	Fund      pay in and mint nothing, so every existing share is worth more
//	Propose   any member opens an advisory question
//	Vote      weighted by the shares you hold, changeable while it is open
//	Close     anyone, once the deadline has gone by
//	Ragequit  burn your shares, be credited your slice, leave
//	Withdraw  collect what you were credited
//
// # The shares are the token
//
// There is no second asset to issue. A share is the vote weight and the claim
// on the treasury at the same moment, minted by paying in and burned by
// leaving, so nothing about it is decorative and nobody has to be persuaded it
// is worth something. v0 keeps the shares as an internal ledger rather than one
// GRC20 per crew, because a GRC20 per crew means a realm per crew. A
// transferable share belongs in [gno.land/p/moul/x/social/coin], the sibling
// that refuses to exist until its mint rule, sink and buyer are declared; this
// realm does not import it.
//
// # The custody caveat, which is real
//
// ONE realm address holds EVERY crew's treasury, with per-crew accounting
// inside it. The chain sees one balance; which crew owns which part of it is a
// number in this realm's state. So a bug in the accounting is a bug across
// crews, not inside one: an arithmetic error that over-credits one crew's
// ragequit pays it out of another crew's money, and nothing at the bank layer
// would refuse that transfer.
//
// The fix is the instance-per-realm pattern (EFFECTIVE_GNO.md section 1.4): one
// realm per crew, each holding its own coins at its own address, with this
// package as the shared engine. That is v1. It is not v0 because deploying a
// realm per crew is a publish per crew, which is the opposite of "create it in
// one transaction", and the whole product claim here is the one transaction.
//
// # Payouts are pulled
//
// Nothing is ever pushed. A ragequit credits an internal ledger and the leaver
// calls [Withdraw] themselves, so one address that cannot be paid cannot wedge
// anybody else, and the credit is zeroed before the coins move.
package crews

import (
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/x/envelope/v0"
	"gno.land/p/moul/x/social/crew/v0"
	"gno.land/p/moul/xmath/v1"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the runtime, because every
// plain read this realm exports reports its CALLER and would build every link
// against the wrong realm.
const realmPath = "gno.land/r/moul/x/social/crews/v0"

// denom is the only coin a crew holds. ugnot and nothing else: a treasury that
// can hold several denominations needs a per-denomination share price, which is
// a different product.
const denom = "ugnot"

// IndexCrews is how many crews the index page lists.
const IndexCrews = 20

// IndexProposals is how many of a crew's proposals its page lists.
//
// Finding 325-cost-at-caps-1: the page rendered every proposal a crew had ever
// had. Proposing is open to every member and nothing deletes one, so the cost
// every reader pays grew without a bound anybody controls.
const IndexProposals = 20

// crews holds every crew, every proposal and the credit ledger. A redeploy
// wipes it, which is the trade gnomod.toml's private = true makes: see the
// comment there.
var crews = crew.New()

// Create opens a crew and makes the caller its first member.
//
// Send ugnot with the call: the founder's shares are bought out of it at
// crew.InitialPricePerShare, and the whole amount, remainder included, becomes
// the treasury. Returns the new crew's id.
func Create(cur realm, name string) int64 {
	// Both checks have to be here and not behind a helper. cur.IsCurrent()
	// before cur.Previous() is the realm-token rule; IsUserCall before the
	// envelope read is the payment one, because the envelope reports what
	// the SIGNER attached to the transaction and not what reached this
	// realm. Without it a realm the user called keeps the coins and calls
	// in here as many times as it likes, every call reading the same send.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, crew.InitialPricePerShare)

	id, err := crews.Create(name, who, amount, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Create",
		"crew", id.String(),
		"founder", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return int64(id)
}

// Join mints the caller shares at what a share is worth right now and adds what
// they sent to the treasury. Returns the shares minted.
//
// The price is amount * totalShares / treasury, rounded down, so somebody
// joining a crew that has tripled its money pays three times what the founders
// did. Send at least the crew page's join price, treasury / totalShares rounded
// up, or there is no whole share to mint.
func Join(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	id := store.ID(crewID)
	c, ok := crews.Get(id)
	if !ok {
		panic(crew.ErrNoCrew.Error())
	}
	amount := envelope.RequireAtLeast(denom, joinPrice(c))

	shares, err := crews.Join(id, who, amount)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Join",
		"crew", id.String(),
		"member", who.String(),
		"amount", strconv.FormatInt(amount, 10),
		"shares", strconv.FormatInt(shares, 10),
	)
	return shares
}

// joinPrice is the least a joiner can send and still be minted a share: the
// floor Join's envelope guard enforces, and the price a crew page quotes.
//
// The engine mints amount * totalShares / treasury, rounded down, so one whole
// share needs treasury / totalShares rounded UP. crew.Crew.PricePerShare rounds
// down, which is one ugnot short whenever the treasury is not an exact multiple
// of the share count, the ordinary state after any Fund: a joiner paying the
// quoted price passed the guard and then reverted on "buys no whole share".
// That method lives in a published package and cannot change in place, so the
// rule is here, next to the only guard that uses it. A crew nobody holds a
// share in is back at the opening price, the same branch Join takes.
func joinPrice(c *crew.Crew) int64 {
	if c.TotalShares == 0 || c.Treasury == 0 {
		return crew.InitialPricePerShare
	}
	return xmath.MulDivUp(1, c.Treasury, c.TotalShares)
}

// Fund adds what the caller sent to a crew's treasury and mints nothing, so
// every existing share is worth more afterwards.
//
// It is how revenue, a grant or a member topping the pot up arrives. Anyone may
// fund any crew, member or not: there is no way to refuse a transfer on this
// chain anyway, and pretending otherwise would only move the donation to a bank
// send the realm cannot account for.
func Fund(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, 1)

	if err := crews.Fund(store.ID(crewID), amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("Fund",
		"crew", store.ID(crewID).String(),
		"from", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Propose opens an advisory question on a crew. Any member may propose, and it
// stays open for crew.VoteBlocks blocks. Returns the proposal's id.
//
// A proposal EXECUTES NOTHING. Passing one records that the crew agreed by
// share weight, and moves no coins, changes no membership and binds no code.
// Executing a payout is the next step and it is not in v0.
func Propose(cur realm, crewID int64, text string) int64 {
	who := caller(cur)
	pid, err := crews.Propose(store.ID(crewID), who, text, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Propose",
		"crew", store.ID(crewID).String(),
		"proposal", pid.String(),
		"author", who.String(),
	)
	return int64(pid)
}

// Vote records the caller's ballot, weighted by the shares they hold at this
// moment. One ballot per member, changeable while the proposal is open.
func Vote(cur realm, proposalID int64, yes bool) {
	who := caller(cur)
	pid := store.ID(proposalID)
	if err := crews.Vote(pid, who, yes, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote",
		"proposal", pid.String(),
		"voter", who.String(),
		"yes", strconv.FormatBool(yes),
	)
}

// Close records a proposal as passed or failed once its deadline has gone by,
// and returns which. Anyone may call it: closing is bookkeeping, not authority.
func Close(cur realm, proposalID int64) bool {
	pid := store.ID(proposalID)
	passed, err := crews.Close(pid, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Close", "proposal", pid.String(), "passed", strconv.FormatBool(passed))
	return passed
}

// Ragequit burns every share the caller holds, credits them their pro-rata
// slice of the treasury and removes them from the crew. Returns the amount
// credited, which [Withdraw] collects.
//
// Nobody has to agree. That is what makes a share mean something: the exit is
// priced by the same number that votes, and a member outvoted on everything can
// still leave with what they put in plus their part of what the crew built.
func Ragequit(cur realm, crewID int64) int64 {
	who := caller(cur)
	id := store.ID(crewID)
	shares, amount, err := crews.Ragequit(id, who)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Ragequit",
		"crew", id.String(),
		"member", who.String(),
		"shares", strconv.FormatInt(shares, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Withdraw sends the caller everything they have been credited, and returns it.
//
// The credit is zeroed before the coins move, so a reentrant call finds nothing
// left to take. Nothing in this realm ever pushes value: one address that
// cannot be paid must not be able to wedge everybody else.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := crews.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns a crew's name, the height it was created at, how many members it
// has, its total shares and its treasury in ugnot.
//
// Flat values rather than the crew itself: handing out a pointer to live state
// is a mutation handle nothing checks, and a struct is not something a wallet
// can decode anyway.
func Get(crewID int64) (string, int64, int, int64, int64) {
	c, ok := crews.Get(store.ID(crewID))
	if !ok {
		return "", 0, 0, 0, 0
	}
	return c.Name, c.CreatedAt, c.MemberCount(), c.TotalShares, c.Treasury
}

// Count is how many crews exist.
func Count() int { return crews.Len() }

// SharesOf is how many shares who holds in a crew.
func SharesOf(crewID int64, who address) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.SharesOf(who)
}

// MemberCount is how many people are in a crew.
func MemberCount(crewID int64) int {
	c, _ := crews.Get(store.ID(crewID))
	return c.MemberCount()
}

// Treasury is what a crew holds, in ugnot. The coins themselves sit at this
// realm's single address: see the package doc on custody.
func Treasury(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	if c == nil {
		return 0
	}
	return c.Treasury
}

// ValuePerShare is what one of a crew's shares is worth in ugnot, rounded down.
func ValuePerShare(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.ValuePerShare()
}

// ProposalOf returns a proposal's crew, author, text, deadline and whether it
// has been closed and passed.
func ProposalOf(proposalID int64) (int64, address, string, int64, bool, bool) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, "", "", 0, false, false
	}
	return int64(p.CrewID), p.Author, p.Text, p.Deadline, p.Closed, p.Passed
}

// Tally is a proposal's share-weighted yes and no.
func Tally(proposalID int64) (int64, int64) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, 0
	}
	return p.Yes, p.No
}

// CreditOf is what an address can withdraw right now, in ugnot.
func CreditOf(who address) int64 { return crews.CreditOf(who) }

// TotalOwed is every outstanding credit, which is the part of this realm's
// balance that belongs to people who have already left.
func TotalOwed() int64 { return crews.TotalOwed() }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package crews

import (
	"strconv"
	"strings"
	"testing"

	"chain"

	"gno.land/p/moul/x/social/crew/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

// The price a crew page shows a joiner, and the floor Join's envelope guard
// enforces, must both be exactly the least amount that mints a whole share.
//
// Join mints amount * totalShares / treasury, rounded down, so that amount is
// treasury / totalShares rounded UP. Rounded down instead, it is one ugnot
// short whenever the treasury is not an exact multiple of the share count,
// which is the ordinary state after any Fund: the page quotes a price, the
// guard accepts it, and the join reverts on "buys no whole share".
//
// The table is over that rule, not over one input: awkward remainders where
// floor and ceiling differ, exact multiples where they must not, and a crew
// everybody left, where the opening price applies.
func TestTheShownPriceBuysAShareAndOneLessIsRefusedByTheGuard(cur realm, t *testing.T) {
	cases := []struct {
		name   string
		create int64 // what the founder pays in, at the opening price
		fund   int64 // then funded with this, which mints nothing
		leave  bool  // then the founder ragequits, leaving an empty crew
		want   int64 // the least amount that mints one share
	}{
		{"treasury 3001 over 2 shares", 2000, 1001, false, 1501},
		{"treasury 3001 over 3 shares", 3000, 1, false, 1001},
		{"ten GNOT and seven ugnot over 10000 shares", tenGNOT, 7, false, 1001},
		{"ten GNOT and 999 ugnot over 10000 shares", tenGNOT, 999, false, 1001},
		{"exact multiple at the opening price", tenGNOT, 0, false, 1000},
		{"exact multiple after doubling", tenGNOT, tenGNOT, false, 2000},
		{"a single share", 1000, 0, false, 1000},
		{"everybody left", 1000, 0, true, crew.InitialPricePerShare},
	}
	for _, tc := range cases {
		reset()
		id := create(cur, alice, tc.create, "crew")
		if tc.fund > 0 {
			fund(cur, carol, tc.fund, id)
		}
		if tc.leave {
			testing.SetRealm(testing.NewUserRealm(alice))
			Ragequit(cross(cur), id)
		}

		// The oracle, independent of the code under test: the least a with
		// a * shares >= treasury, or the opening price when nobody holds one.
		_, _, _, shares, treasury := Get(id)
		oracle := crew.InitialPricePerShare
		if shares > 0 && treasury > 0 {
			oracle = treasury / shares
			if treasury%shares != 0 {
				oracle++
			}
		}
		urequire.Equal(t, tc.want, oracle, tc.name+": the table agrees with the rule")

		page := Render("crew/" + strconv.FormatInt(id, 10))
		uassert.Equal(t, tc.want, shownPrice(t, page),
			tc.name+": the page quotes what buys a share: "+page)

		// One ugnot under it is refused by the envelope guard, which names the
		// real price, rather than by Join after the guard let it through.
		testing.IssueCoins(realmAddr, chain.Coins{{denom, tc.want - 1}})
		testing.SetOriginSend(chain.Coins{{denom, tc.want - 1}})
		testing.SetRealm(testing.NewUserRealm(bob))
		uassert.AbortsContains(t, cur, "costs at least "+strconv.FormatInt(tc.want, 10)+denom,
			func() { Join(cross(cur), id) }, tc.name+": the guard refuses one ugnot short")

		// Exactly the quoted price buys exactly one share.
		got := join(cur, bob, tc.want, id)
		uassert.Equal(t, int64(1), got, tc.name+": the quoted price mints one share")
	}
}

// shownPrice reads the price cell of a crew page's summary table, the first
// row after the header that starts with "| members", in ugnot. It is keyed on
// the row's position, not the column's title, so it reads the same cell
// whatever that column is called.
func shownPrice(t *testing.T, page string) int64 {
	lines := strings.Split(page, "\n")
	for i, l := range lines {
		if !strings.HasPrefix(l, "| members") {
			continue
		}
		urequire.True(t, i+2 < len(lines), "the summary table has a row: "+page)
		cells := strings.Split(lines[i+2], "|")
		urequire.Equal(t, 6, len(cells), "four cells: "+lines[i+2])
		return parseGNOT(t, strings.TrimSpace(cells[4]))
	}
	t.Fatalf("no summary table on the crew page: %s", page)
	return 0
}

// parseGNOT turns num.GNOTf's "1.0015 GNOT" back into ugnot.
func parseGNOT(t *testing.T, s string) int64 {
	urequire.True(t, strings.HasSuffix(s, " GNOT"), "a GNOT amount: "+s)
	s = strings.TrimSuffix(s, " GNOT")
	whole, frac := s, ""
	if i := strings.Index(s, "."); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	urequire.True(t, len(frac) <= 6, "at most six decimals: "+s)
	frac += strings.Repeat("0", 6-len(frac))
	w, err := strconv.ParseInt(whole, 10, 64)
	urequire.NoError(t, err, s)
	f, err := strconv.ParseInt(frac, 10, 64)
	urequire.NoError(t, err, s)
	return w*1000000 + f
}

package crews

import (
	"strconv"

	"chain/runtime"

	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/x/social/crew/v0"
	"gno.land/p/moul/xmath/v1"
)

// Render routes three views: the index, one crew, and one proposal.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch req.PathPart(0) {
	case "":
		return renderIndex()
	case "crew":
		return renderCrew(req.PathPart(1))
	case "proposal":
		return renderProposal(req.PathPart(1))
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Crews")
	out += "Three to fifteen people with a shared pot, a way to decide, and a way to " +
		"leave with their share. One transaction to start one.\n\n"

	t := ui.NewTable("crews", "proposals", "owed to people who left")
	t.Row(
		strconv.Itoa(crews.Len()),
		strconv.Itoa(crews.ProposalCount()),
		num.GNOTf(crews.TotalOwed()),
	)
	out += t.String()

	out += md.H2("The crews")
	out += crewTable(crews.List(IndexCrews))

	out += "\n" + ui.Action("Start a crew", "Create", "name", "") + "\n"

	out += md.H2("How a share works")
	out += md.BulletList([]string{
		"A share is the vote weight and the claim on the treasury at once. There is no second token.",
		"Joining mints shares at what a share is worth NOW: " +
			md.InlineCode("amount * totalShares / treasury") +
			", rounded down, so a late joiner cannot buy into value the others built.",
		"Ragequitting burns every share you hold and credits you " +
			md.InlineCode("shares * treasury / totalShares") +
			", rounded down. Nobody has to agree.",
		"Both round in the crew's favour. The last member out holds every share, " +
			"so the treasury still empties to the last ugnot.",
		"A proposal is advisory text. Passing one records agreement and executes nothing.",
	})

	out += md.H2("Custody")
	out += "One realm address holds every crew's treasury, with per-crew accounting " +
		"inside. A bug in that accounting is a bug across crews, not inside one. " +
		"The fix is one realm per crew, and it is v1.\n"

	return out
}

func renderCrew(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a crew id: " + ui.Inline(raw)
	}
	c, found := crews.Get(id)
	if !found {
		return md.H1("Crews") + "No crew #" + id.String()
	}

	out := md.H1(ui.Inline(c.Name))
	out += md.Italic("crew #"+id.String()+" · opened at block "+
		strconv.FormatInt(c.CreatedAt, 10)) + "\n\n"

	t := ui.NewTable("members", "shares", "treasury", "to join")
	t.Row(
		strconv.Itoa(c.MemberCount())+" of "+strconv.Itoa(crew.MaxMembers),
		strconv.FormatInt(c.TotalShares, 10),
		num.GNOTf(c.Treasury),
		num.GNOTf(joinPrice(c)),
	)
	out += t.String()

	out += md.H2("Members")
	if c.MemberCount() == 0 {
		out += ui.Empty("Everybody has left. The next member in pays the opening price again.")
	} else {
		m := ui.NewTable("member", "shares", "weight", "worth")
		for _, who := range c.Members() {
			shares := c.SharesOf(who)
			m.Row(
				ui.Addr(who),
				strconv.FormatInt(shares, 10),
				num.Pct(xmath.MulDiv(shares, 10000, c.TotalShares)),
				num.GNOTf(xmath.MulDiv(shares, c.Treasury, c.TotalShares)),
			)
		}
		out += m.String()
	}

	out += md.H2("Proposals")
	out += proposalTable(c.Proposals())
	out += "\nA proposal is advisory text. Passing one records that the crew agreed " +
		"by share weight, and executes nothing.\n"

	out += "\n" + ui.Join(" · ",
		ui.Action("Join", "Join", "crewID", id.String()),
		ui.Action("Fund", "Fund", "crewID", id.String()),
		ui.Action("Propose", "Propose", "crewID", id.String(), "text", ""),
		ui.Action("Ragequit", "Ragequit", "crewID", id.String()),
	) + "\n"
	return out
}

func renderProposal(raw string) string {
	pid, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a proposal id: " + ui.Inline(raw)
	}
	p, found := crews.Proposal(pid)
	if !found {
		return md.H1("Crews") + "No proposal #" + pid.String()
	}

	out := md.H1("Proposal #" + pid.String())
	out += md.Blockquote(ui.Inline(p.Text)) + "\n"

	crewName := "crew #" + p.CrewID.String()
	if c, ok := crews.Get(p.CrewID); ok {
		crewName = c.Name
	}
	out += md.Italic("by "+ui.Addr(p.Author)+" · in "+
		md.Link(ui.ShortN(crewName, crew.ExcerptLen, 0), crewURL(p.CrewID))) + "\n\n"

	now := runtime.ChainHeight()
	t := ui.NewTable("state", "yes", "no", "voters")
	t.Row(
		state(p, now),
		strconv.FormatInt(p.Yes, 10),
		strconv.FormatInt(p.No, 10),
		strconv.Itoa(p.Voters()),
	)
	out += t.String()

	if p.Open(now) {
		out += "\n" + ui.Join(" · ",
			ui.Action("Vote yes", "Vote", "proposalID", pid.String(), "yes", "true"),
			ui.Action("Vote no", "Vote", "proposalID", pid.String(), "yes", "false"),
		) + "\n"
	} else if !p.Closed {
		out += "\n" + ui.Action("Close it", "Close", "proposalID", pid.String()) + "\n"
	}
	return out
}

// crewTable lists crews, newest first.
func crewTable(items []crew.Listing) string {
	t := ui.NewTable("crew", "members", "shares", "treasury")
	for _, it := range items {
		t.Row(
			// ShortN truncates without escaping and md.Link escapes what it
			// is given: ui.Inline here would escape twice and render the
			// backslashes. A pipe is what md.Link's escaper does NOT cover,
			// which is why crew.ValidName refuses one at write time.
			md.Link(ui.ShortN(it.Crew.Name, crew.ExcerptLen, 0), crewURL(it.ID)),
			strconv.Itoa(it.Crew.MemberCount()),
			strconv.FormatInt(it.Crew.TotalShares, 10),
			num.GNOTf(it.Crew.Treasury),
		)
	}
	return t.OrEmpty("No crews yet.")
}

// proposalTable lists a crew's proposals, newest first.
//
// The link title is the id and not the text, which is the opposite of
// crewTable and deliberate: a proposal's text is free prose and may contain a
// pipe, md.Link's escaper leaves pipes alone, and a pipe in a link title inside
// a table cell opens a column. So the chrome carries the link and the prose
// goes through ui.Cell, which is the escaper that knows it is in a table.
func proposalTable(ids []store.ID) string {
	now := runtime.ChainHeight()
	// Finding 325-cost-at-caps-1: this rendered every proposal a crew has
	// ever had, and proposing is open to every member with no delete path.
	// Newest first already, so the bound is on where the walk stops.
	total := len(ids)
	stop := 0
	if total > IndexProposals {
		stop = total - IndexProposals
	}
	t := ui.NewTable("#", "proposal", "state", "yes", "no")
	for i := total - 1; i >= stop; i-- {
		p, ok := crews.Proposal(ids[i])
		if !ok {
			continue
		}
		t.Row(
			md.Link("#"+ids[i].String(), proposalURL(ids[i])),
			// Cut on a rune boundary first, escape once after: escaping
			// first and cutting after can strand a lone backslash.
			ui.Cell(ui.ShortN(p.Text, crew.ExcerptLen, 0)),
			state(p, now),
			strconv.FormatInt(p.Yes, 10),
			strconv.FormatInt(p.No, 10),
		)
	}
	out := t.OrEmpty("Nothing has been proposed yet.")
	if total > IndexProposals {
		out += md.Italic("Showing the newest "+strconv.Itoa(IndexProposals)+" of "+
			strconv.Itoa(total)+" proposals.") + "\n"
	}
	return out
}

// state is the one word a proposal is in at height now.
func state(p *crew.Proposal, now int64) string {
	switch {
	case p.Open(now):
		return "open until " + strconv.FormatInt(p.Deadline, 10)
	case !p.Closed:
		return "awaiting a close"
	case p.Passed:
		return "passed"
	default:
		return "failed"
	}
}

// crewURL is the gnoweb path of one crew.
func crewURL(id store.ID) string { return realmURL() + ":crew/" + id.String() }

// proposalURL is the gnoweb path of one proposal.
func proposalURL(id store.ID) string { return realmURL() + ":proposal/" + id.String() }

// realmURL is this realm's gnoweb path. The chain domain is the first element
// of a package path and a gnoweb path is the rest of it, so this is a prefix
// strip and not a hostname the realm has to know.
func realmURL() string {
	for i := 0; i < len(realmPath); i++ {
		if realmPath[i] == '/' {
			return realmPath[i:]
		}
	}
	return "/" + realmPath
}

// Package devtools is the worked example of wiring moul's developer packages
// into one realm: what a new realm should copy.
//
// Everything here is a COMBINATION. Any one of these packages has its own demo
// showing it alone; the thing that is hard to find is what they look like used
// together, which is the only form a real realm ever meets them in. So this
// realm imports ten of them and every one earns its place in the output:
//
//	r/moul/config     the notice block, the pause switch, the explorer to link
//	p/moul/mygnoscan  the explorer routes themselves
//	p/moul/debug      a metadata panel behind ?debug=1
//	p/moul/realmpath  reading the query string Render was handed
//	p/moul/kit/ui     escaping what a caller typed, and the tables
//	p/moul/md         the markdown, without hand-rolled strings
//	p/moul/txlink     the "call this function" link
//	p/moul/fifo       the bounded note list, so the state cannot grow forever
//	p/moul/kit/tally  the note leaderboard, ties ordered rather than arbitrary
//	p/moul/kit/num    pricing that list in GNOT rather than raw ugnot
//
// # The three lines worth copying
//
// A realm that does nothing else should still do these:
//
//	func Render(path string) string {
//		return config.TopBlockFor(realmPath) + body + config.BottomBlockFor(realmPath)
//	}
//
//	func Mutate(cur realm, s string) {
//		config.AssertWritableFor(realmPath)  // honours the pause switch
//		notes.Append(ui.Inline(s))           // escapes what a caller typed
//	}
//
// The first gives every realm a place to put a warning and a pause banner
// without shipping banner code. The second is two separate guards that both
// have to be there: the pause one so an incident can stop writes from outside
// the realm, and the escaping one because a string a caller typed is the
// oldest way to break a page.
package devtools

import (
	"strconv"
	"strings"

	"chain/markdown"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/moul/debug/v0"
	"gno.land/p/moul/fifo/v0"
	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/tally/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/mygnoscan/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/r/moul/config/v1"
)

// realmPath is this realm's own path.
//
// Passed explicitly to config rather than relying on its zero-argument helpers.
// Both work (a plain read is borrowed, so config sees this realm as the
// caller), but a constant cannot be wrong, and spelling it out is what a reader
// copying this file needs to see.
const realmPath = "gno.land/r/moul/x/allinone/devtools/v0"

// maxNotes bounds the guest list. fifo drops the oldest rather than growing,
// because storage on chain is paid for and never refunded: an unbounded list in
// a demo anyone can write to is a bill with no ceiling.
const maxNotes = 10

var notes = fifo.New(maxNotes)

// authors counts notes per writer. A tally.Board rather than a map: gno map
// iteration order is unspecified, so a leaderboard built by ranging one is not
// reproducible between calls.
var authors = tally.NewBoard()

// depositPerByte is what the chain charges to keep a byte, in ugnot. Used only
// to price the note list on the page, never to settle anything.
const depositPerByte = 100

// Add appends a note. It is the only mutating function here, and it carries
// both guards a real one should.
func Add(cur realm, body string) {
	// 1. The pause switch. Set `pause@r/moul/x/allinone/devtools` on
	//    r/moul/config and this aborts, with the reason, from outside this
	//    realm and without a redeploy.
	config.AssertWritableFor(realmPath)

	body = strings.TrimSpace(body)
	if strings.TrimSpace(markdown.StripBidiAndZeroWidth(body)) == "" {
		panic("empty note")
	}
	if len(body) > 200 {
		panic("note too long: max 200 bytes, got " + strconv.Itoa(len(body)))
	}

	// 2. Escaping. body is a string a caller typed, and it is about to land in
	//    a markdown list. ui.Inline is the repo's standard for exactly this.
	notes.Append(ui.Inline(body))

	// 3. The scoreboard. tally.Board keeps one score per author and orders
	//    ties by key, so two authors on the same count always render in the
	//    same order.
	authors.Add(unsafe.PreviousRealm().Address().String(), 1)
}

// Reset empties the list, so the realm can be put back to a known state
// without a redeploy. Not gated by the pause switch: clearing up is the thing
// you still want to do while paused.
func Reset(cur realm) {
	notes = fifo.New(maxNotes)
	authors = tally.NewBoard()
}

// Render shows every package at work. The root view is deliberately free of
// anything that moves on its own, so an example test can pin it; the live
// numbers live under "chain".
func Render(path string) string {
	req := realmpath.Parse(path)

	var b strings.Builder
	b.WriteString(config.TopBlockFor(realmPath))
	b.WriteString(md.H1("allinone: devtools"))
	b.WriteString("\nTen packages, used together rather than one at a time. ")
	b.WriteString(md.Link("source", config.MygnoscanFor(realmPath)))
	b.WriteString("\n\n")

	switch req.PathPart(0) {
	case "chain":
		b.WriteString(renderChain())
	default:
		b.WriteString(renderHome(path))
	}

	// debug prints its own panel only when ?debug=1 is set, and the empty
	// string otherwise, so this line is safe to leave in a deployed realm.
	b.WriteString(debug.Render(path))
	b.WriteString(config.BottomBlockFor(realmPath))
	return b.String()
}

func renderHome(path string) string {
	var b strings.Builder

	b.WriteString(md.H2("Notes"))
	b.WriteString("\n")
	// renderNotes returns no trailing newline of its own: md.BulletList and
	// ui.Empty already end in one, and adding a second here produced two
	// consecutive blank lines, which gno collapses inside an // Output: block
	// and which therefore no example test can ever pin.
	b.WriteString(renderNotes())
	b.WriteString("\n")

	// txlink builds the "call this function" URL for the CURRENT realm, so it
	// keeps working after a version bump without anything here changing.
	b.WriteString(md.BulletList([]string{
		md.Link("add a note", txlink.NewLink("Add").AddArgs("body", "hello").URL()),
		md.Link("clear them", txlink.Call("Reset")),
		md.Link("live chain values", "/r/moul/x/allinone/devtools/v0:chain"),
		md.Link("toggle the debug panel", debug.ToggleURL(path)),
	}))
	b.WriteString("\n")

	b.WriteString(renderBoard())

	b.WriteString(md.H2("What each package does here"))
	b.WriteString("\n")
	t := ui.NewTable("package", "what it contributed")
	t.Row("`r/moul/config`", "the notice block above, the pause guard on `Add`, and which explorer to link")
	t.Row("`p/moul/mygnoscan`", "the explorer routes, so a link survives a route change")
	t.Row("`p/moul/debug`", "the `?debug=1` panel, empty otherwise")
	t.Row("`p/moul/realmpath`", "splitting the render path into a view and a query")
	t.Row("`p/moul/kit/ui`", "escaping a caller's note, and this table")
	t.Row("`p/moul/md`", "every heading, link and list on the page")
	t.Row("`p/moul/txlink`", "the call links above, relative to this realm")
	t.Row("`p/moul/fifo`", "the note list, bounded so storage cannot grow forever")
	t.Row("`p/moul/kit/tally`", "the note leaderboard, with ties ordered by address")
	t.Row("`p/moul/kit/num`", "pricing the note list in GNOT instead of raw ugnot")
	b.WriteString(t.String())

	return b.String()
}

// renderBoard shows who has written the most notes, and what the list costs to
// keep. Both numbers come from a package rather than from arithmetic here.
func renderBoard() string {
	var b strings.Builder
	b.WriteString(md.H2("Who has written the most"))
	b.WriteString("\n")

	top := authors.Top(5)
	if len(top) == 0 {
		b.WriteString(ui.Empty("No notes yet, so nobody is on the board."))
	} else {
		t := ui.NewTable("#", "author", "notes")
		for i, e := range top {
			t.Row(ui.Podium(i+1), ui.AddrOf(e.Key), num.Pad(e.Score, 2))
		}
		b.WriteString(t.String())
	}

	// num.GNOTf, not a hand-rolled divide by a million. The storage deposit is
	// what the chain charges to keep these bytes, so it is the honest price of
	// the list above.
	b.WriteString("\nStorage deposit for the list: **")
	b.WriteString(num.GNOTf(int64(notesBytes()) * depositPerByte))
	b.WriteString("**\n\n")
	return b.String()
}

// notesBytes is the length of every note currently held.
func notesBytes() int {
	n := 0
	for _, v := range notes.Entries() {
		n += len(v.(string))
	}
	return n
}

// renderChain is everything that moves: the height, and the links built from
// it. Kept off the root view so the root can be pinned by an example.
func renderChain() string {
	s := config.Scanner()
	h := runtime.ChainHeight()

	var b strings.Builder
	b.WriteString(md.H2("Live"))
	b.WriteString("\n")

	t := ui.NewTable("what", "value")
	t.Row("chain id", ui.Cell(runtime.ChainID()))
	t.Row("height", strconv.FormatInt(h, 10))
	t.Row("explorer", ui.Cell(s.Base()))
	t.Row("network", ui.Cell(s.Network()))
	b.WriteString(t.String())
	b.WriteString("\n")

	// mygnoscan.Link used directly, rather than through config, to show that
	// the builder is an ordinary value: config only decides where it points.
	b.WriteString(md.BulletList([]string{
		mygnoscan.Link("this block", s.Block(h)),
		mygnoscan.Link("this realm's transactions", s.Realm(realmPath, mygnoscan.TabCalls)),
		mygnoscan.Link("its dependency graph", s.Realm(realmPath, mygnoscan.TabDeps)),
		mygnoscan.Link("the parked deploy queue", s.Packages(mygnoscan.PackagesInert)),
	}))
	b.WriteString("\n")
	b.WriteString(md.Link("back", "/r/moul/x/allinone/devtools/v0"))
	b.WriteString("\n")
	return b.String()
}

func renderNotes() string {
	if notes.Size() == 0 {
		return ui.Empty("no notes yet")
	}
	items := []string{}
	for _, e := range notes.Entries() {
		items = append(items, e.(string))
	}
	return md.BulletList(items)
}

